    lp = json.loads(lp) if lp else {}
    v = lp.get("video") or {}
    cands = lp.get("candidates") or []
    ids = [x["video_id"] for x in cands]
    print(slug[:35].ljust(35), lp.get("status"), lp.get("method"), lp.get("transcript_method"), "pos", ids.index(v["video_id"]) if v.get("video_id") in ids else None, "views", v.get("views"), [x.get("views") for x in cands][:4], "stt_checked", lp.get("stt_checked"), "summary_len", len(lp.get("summary") or ""))
for r in c.execute("select id, trigger, status, selected, ok, failed, message from runs"): print(r)
for r in c.execute("select step, substr(message,1,150) from errors"): print(r)
EOF
done

