  4	  });
  5	
  6	  var TZ = (document.body && document.body.dataset.tz) || undefined;
  7	  var STATUS = {
  8	    idle: "ожидает", running: "работает", waiting: "ждёт запуска", ok: "в норме", error: "ошибка",
  9	    off: "выключен", partial: "частично", failed: "сбой", empty: "нечего обрабатывать", interrupted: "прерван",
 10	    cut: "остановлен по времени", skipped: "пропускается"
 11	  };
 12	  var TRIGGER = { manual: "вручную", schedule: "по расписанию", startup: "при старте" };
 13	
 14	  function esc(s) {
 15	    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
 16	      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
 17	    });
 18	  }
 19	
 20	  function fmt(iso) {
 21	    if (!iso) return "—";
 22	    var d = new Date(iso);
 23	    if (isNaN(d)) return String(iso);
 24	    try {
 25	      return new Intl.DateTimeFormat("ru-RU", {
 26	        timeZone: TZ, day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit"
 27	      }).format(d).replace(",", "");
 28	    } catch (e) {
 29	      return d.toLocaleString("ru-RU");
 30	    }
 31	  }
 32	
 33	  function wait(seconds) {
 34	    seconds = Math.max(0, Math.ceil(seconds));
 35	    var m = Math.floor(seconds / 60), s = seconds % 60;
 36	    return m + ":" + (s < 10 ? "0" : "") + s;
 37	  }
 38	
 39	  function setText(id, value) {
 40	    var el = document.getElementById(id);
 41	    if (el) el.textContent = value;
 42	  }
 43	
 44	  function setProgress(pct) {
 45	    var bar = document.getElementById("progress-bar");
 46	    if (bar) bar.style.width = Math.max(0, Math.min(100, pct || 0)) + "%";
 47	  }
 48	
 49	  var manual = null;
 50	  var pending = false;
 51	
 52	  function renderButton() {
 53	    var btn = document.getElementById("run-btn");
 54	    var hint = document.getElementById("run-hint");
 55	    if (!btn || pending || !manual) return;
 56	    var text = "Запустить обработку сейчас";
 57	    var disabled = false;
 58	    var hintText = "Ручных запусков сегодня: " + manual.runs_today + (manual.daily_cap ? " из " + manual.daily_cap : "") +
 59	      ". После каждого запуска пауза " + Math.round(manual.cooldown_seconds / 60) + " мин.";
 60	    if (manual.code === "busy") {
 61	      text = "Обработка идёт…";
 62	      disabled = true;
 63	    } else if (manual.code === "cooldown" || manual.code === "cap") {
 64	      var left = manual.available_at ? (new Date(manual.available_at) - Date.now()) / 1000 : manual.retry_after;
 65	      if (left > 0) {
 66	        disabled = true;
 67	        text = manual.code === "cap" ? "Лимит ручных запусков на сегодня" : "Запуск через " + wait(left);
 68	        hintText = manual.reason || hintText;
 69	      }
