 79	    document.getElementById("run-dot").className = "dot " + (running ? "running" : "idle");
 80	    setText("run-state", running ? "Идёт обработка" : "Ожидание");
 81	    setText("run-step", p.step ? p.step + (p.current && p.step.indexOf(p.current) < 0 ? ": " + p.current : "") : "");
 82	    setProgress(p.total ? Math.round(100 * p.done / p.total) : 0);
 83	    setText("progress-text", p.total
 84	      ? "Запуск #" + p.run_id + ": " + p.done + " из " + p.total + " · успешно " + p.ok + ", ошибок " + p.failed
 85	      : "Нет активной обработки");
 86	
 87	    manual = st.manual || manual;
 88	    renderButton();
 89	
 90	    var t = st.totals || {};
 91	    setText("t-total", t.games_total);
 92	    setText("t-today", t.processed_today);
 93	    setText("t-today-sub", "успешно " + t.processed_today_ok + " · " + st.day);
 94	    setText("t-errors", t.errors_today);
 95	    setText("t-errors-sub", "всего " + t.errors_total);
 96	    var last = st.last_run;
