  1	{% extends "base.html" %}
  2	{% block title %}Мониторинг · Игры Metacritic{% endblock %}
  3	{% block content %}
  4	{% set m = st.manual %}
  5	<div class="page-head">
  6	  <div>
  7	    <h1>Мониторинг сервиса</h1>
  8	    <p class="muted">Обработка запускается каждые {{ st.config.interval_minutes }} мин, за раз до {{ st.config.batch_size }} игр, не дольше {{ st.config.run_max_minutes }} мин. Страница обновляется в реальном времени.</p>
  9	  </div>
 10	  <form method="post" action="/run" id="run-form" class="run-box" data-available-at="{{ m.available_at or '' }}" data-code="{{ m.code }}" data-runs-today="{{ m.runs_today }}" data-daily-cap="{{ m.daily_cap }}" data-cooldown="{{ m.cooldown_seconds }}" data-retry-after="{{ m.retry_after }}" data-reason="{{ m.reason }}">
 11	    <button class="btn" type="submit" id="run-btn" {% if not m.allowed %}disabled{% endif %}>
 12	      {%- if m.code == 'busy' %}Обработка идёт…{% elif m.code == 'cooldown' %}Запуск через {{ m.retry_after|wait }}{% elif m.code == 'cap' %}Лимит ручных запусков на сегодня{% else %}Запустить обработку сейчас{% endif -%}
 13	    </button>
 14	    <span class="run-hint" id="run-hint">{% if m.code in ('cooldown', 'cap') %}{{ m.reason }}{% else %}Ручных запусков сегодня: {{ m.runs_today }}{% if m.daily_cap %} из {{ m.daily_cap }}{% endif %}. После каждого запуска пауза {{ (m.cooldown_seconds // 60) }} мин.{% endif %}</span>
 15	  </form>
 16	</div>
 17	
 18	{% if started %}<div class="banner ok" id="flash">Обработка запущена.</div>
 19	{% elif busy %}<div class="banner" id="flash">Обработка уже идёт, второй запуск не нужен.</div>
 20	{% elif wait %}<div class="banner" id="flash">Запуск отклонён: после предыдущей обработки должно пройти {{ (m.cooldown_seconds // 60) }} мин. Попробуйте через {{ wait|wait }}.</div>
 21	{% elif cap %}<div class="banner" id="flash">Запуск отклонён: достигнут дневной лимит ручных запусков.</div>
 22	{% elif forbidden %}<div class="banner" id="flash">Запуск разрешён только со страницы мониторинга этого сервиса.</div>
 23	{% else %}<div class="banner" id="flash" hidden></div>{% endif %}
 24	
 25	<section class="card pad">
 26	  <div class="run-line">
 27	    <span class="status-pill"><span class="dot {{ 'running' if st.running else 'idle' }}" id="run-dot"></span><span id="run-state">{{ 'Идёт обработка' if st.running else 'Ожидание' }}</span></span>
 28	    <span class="muted small" id="run-step">{% if st.progress.step %}{{ st.progress.step }}{% if st.progress.current %}: {{ st.progress.current }}{% endif %}{% endif %}</span>
 29	    <span class="conn"><span class="dot" id="conn-dot"></span><span id="conn-text">подключение…</span></span>
 30	  </div>
 31	  <div class="progress"><div id="progress-bar" data-pct="{{ (100 * st.progress.done / st.progress.total)|round|int if st.progress.total else 0 }}"></div></div>
 32	  <div class="muted small" id="progress-text">{% if st.progress.total %}{{ st.progress.done }} из {{ st.progress.total }} · успешно {{ st.progress.ok }}, ошибок {{ st.progress.failed }}{% else %}Нет активной обработки{% endif %}</div>
 33	</section>
 34	
 35	<section class="section tiles">
 36	  <div class="card tile"><div class="label">Игр в базе</div><div class="value" id="t-total">{{ st.totals.games_total }}</div></div>
 37	  <div class="card tile"><div class="label">Обработано сегодня</div><div class="value" id="t-today">{{ st.totals.processed_today }}</div><div class="sub" id="t-today-sub">успешно {{ st.totals.processed_today_ok }} · {{ st.day }}</div></div>
 38	  <div class="card tile"><div class="label">Ошибок сегодня</div><div class="value" id="t-errors">{{ st.totals.errors_today }}</div><div class="sub" id="t-errors-sub">всего {{ st.totals.errors_total }}</div></div>
 39	  <div class="card tile"><div class="label">Последний запуск</div><div class="value sm" id="t-last">{{ st.last_run.started_at|dt if st.last_run else '—' }}</div><div class="sub" id="t-last-sub">{% if st.last_run %}{{ st.last_run.status|status_ru }} · {{ st.last_run.ok }}/{{ st.last_run.selected }}{% endif %}</div></div>
 40	  <div class="card tile"><div class="label">Следующий запуск</div><div class="value sm" id="t-next">{{ st.next_run_at|dt if st.next_run_at else '—' }}</div><div class="sub" id="t-cursor">{% if st.day_state.new_releases_done %}New Releases пройден, SEE ALL с позиции {{ st.day_state.browse_offset }}{% else %}сегодня ещё идёт блок New Releases{% endif %}</div></div>
 41	</section>
 42	
 43	<section class="section">
 44	  <h2>Воркеры</h2>
 45	  <div class="workers" id="workers">
 46	    {% for w in st.workers %}
 47	    <div class="card worker" data-worker="{{ w.name }}">
 48	      <div class="worker-head"><span class="dot {{ w.status }}"></span>{{ w.title }}<span class="st">{{ w.status|status_ru }}</span></div>
 49	      <div class="small muted detail">{{ w.detail or '—' }}</div>
 50	    </div>
 51	    {% endfor %}
 52	  </div>
 53	</section>
 54	
 55	<section class="section card pad">
 56	  <h2>Журнал в реальном времени</h2>
 57	  <div class="log" id="log" aria-live="polite"></div>
 58	</section>
 59	
 60	<div class="section two-col">
 61	  <section class="card pad">
 62	    <h2>Последние запуски</h2>
 63	    <div class="table-scroll">
 64	      <table>
 65	        <thead><tr><th>#</th><th>Старт</th><th>Как</th><th>Итог</th><th>Игры</th></tr></thead>
 66	        <tbody id="runs">
 67	          {% for r in st.runs %}
 68	          <tr><td>{{ r.id }}</td><td>{{ r.started_at|dt }}</td><td>{{ r.trigger|trigger_ru }}</td><td><span class="dot inline {{ r.status }}"></span> {{ r.status|status_ru }}</td><td>{{ r.ok }}/{{ r.selected }}{% if r.failed %}, ошибок {{ r.failed }}{% endif %}</td></tr>
 69	          {% else %}
 70	          <tr><td colspan="5" class="muted">Запусков ещё не было</td></tr>
 71	          {% endfor %}
 72	        </tbody>
 73	      </table>
 74	    </div>
 75	  </section>
 76	  <section class="card pad">
 77	    <h2>Последние ошибки</h2>
 78	    <div class="table-scroll">
 79	      <table>
 80	        <thead><tr><th>Время</th><th>Игра / шаг</th><th>Сообщение</th></tr></thead>
 81	        <tbody id="errors">
 82	          {% for e in st.errors %}
 83	          <tr><td>{{ e.at|dt }}</td><td>{{ e.slug or '—' }}<br><span class="muted small">{{ e.step }}</span></td><td class="small">{{ e.message }}</td></tr>
 84	          {% else %}
 85	          <tr><td colspan="3" class="muted">Ошибок нет</td></tr>
 86	          {% endfor %}
 87	        </tbody>
 88	      </table>
 89	    </div>
 90	  </section>
 91	</div>
 92	
 93	<p class="small muted section">LLM: {{ st.config.llm_model }} ({{ st.config.llm_endpoint }}) · YouTube: {{ 'включён' if st.config.youtube_enabled else 'выключен' }} · планировщик: {{ 'включён' if st.config.scheduler_enabled else 'выключен' }}{% if st.scheduler.enabled and not st.scheduler.healthy %} <span class="badge err">планировщик не отвечает</span>{% endif %} · сервис запущен {{ st.started_at|dt }}</p>
 94	{% endblock %}

